// ---------------------------------------------------------------------------
// Originally written by Jagjit (hard-coded experiment cases). Changes GENERATED BY
// AN LLM: Claude (Anthropic):
//   2026-11-21: fixes to the tile coding / RBF calls and the per-1000-episode averages.
//   2026-11-23: weight saving after each seed; epsilon = 0.02 and a weights folder in
//               the final comparison cases.
//   2026-11-26: rewritten to be driven by command-line options, like train_neural_net,
//               instead of hard-coded cases, with Q-learning or Sarsa (train_loop's
//               RLAlgorithm). The old cases are one command each in
//               tools/run_experiments.sh. Output is unchanged: the same console
//               tables, a save_csv file per run and the weights of every seed.
// ---------------------------------------------------------------------------
// run_q_learning: trains tile coding or RBF keepers and writes one CSV per run.
//
//   ./build/run_q_learning --approx tc|rbf [options]      (--help lists them)
//
// Defaults are the final tuned settings (gamma 0.99, epsilon 0.02, alpha 0.6, 20 tiles
// x 10 tilings, 200 RBF centres with sigma 0.01, 20,000 episodes, 10 seeds), so
//   ./build/run_q_learning --approx tc
// reproduces the cmp-tc-final run. --alpha is the fraction of the TD error moved per
// update; it is divided by the number of active features (variables x tilings for tile
// coding, variables for RBF) before it reaches the approximator.
// ---------------------------------------------------------------------------
#include <filesystem>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

#include "sim/keepaway_env.hpp"
#include "learn/q_learning.hpp"
#include "learn/train.hpp"
#include "common.hpp"

namespace keepaway
{
    const uint64_t seed_multiplier = 100000;

    struct Options
    {
        std::string approx = "";      // tc | rbf
        std::string algo = "qlearn";  // qlearn | sarsa
        std::string features = "full"; // full | reduced
        int episodes = 20000;
        int seeds = 10;
        uint64_t seed = 10;
        double gamma = 0.99;
        double epsilon = 0.02;
        double alpha = 0.6; // fraction of the TD error moved per update
        int tiles = 20;
        int tilings = 10;
        int centres = 200;
        double sigma = 0.01;
        int learners = 3; // 3 = all keepers learn; 1 = keeper 0 learns, the other two are hand-coded
        std::string name = "";
        std::string out_dir = "results";
        std::string weights_dir = "";
    };

    void print_usage(const char *prog)
    {
        std::cout << "Usage: " << prog << " --approx <tc|rbf> [options]\n\n"
                  << "Options:\n"
                  << "  --approx <tc|rbf>         Function approximator (required)\n"
                  << "  --algo <qlearn|sarsa>     RL algorithm (default: qlearn)\n"
                  << "  --features <full|reduced> All 13 state variables, or the 4 reduced ones (default: full)\n"
                  << "  --episodes <N>            Training episodes per seed (default: 20000)\n"
                  << "  --seeds <N>               Number of seeds: seed, seed+100000, ... (default: 10)\n"
                  << "  --seed <N>                First seed (default: 10)\n"
                  << "  --gamma <val>             Discount factor (default: 0.99)\n"
                  << "  --epsilon <val>           Exploration rate (default: 0.02)\n"
                  << "  --alpha <val>             Fraction of the TD error moved per update (default: 0.6)\n"
                  << "  --tiles <N>               Tile coding: tiles per tiling (default: 20)\n"
                  << "  --tilings <N>             Tile coding: tilings per state variable (default: 10)\n"
                  << "  --centres <N>             RBF: centres per state variable (default: 200)\n"
                  << "  --sigma <val>             RBF: Gaussian standard deviation (default: 0.01)\n"
                  << "  --learners <3|1>          Learning keepers; with 1 the other two are hand-coded (default: 3)\n"
                  << "  --name <name>             Run name for the CSV and weights (default: <approx>-<algo>-<features>)\n"
                  << "  --out-dir <path>          Folder for the CSV (default: results)\n"
                  << "  --weights-dir <path>      Folder for per-seed weights (default: results/weights/<name>)\n"
                  << "  --help                    Show this message\n";
    }

    // Trains one seed and saves its weights to <weights_dir>/seed-<seed>.txt.
    std::vector<Episode> train_one(const Options &o, const std::vector<Feature> &features, const Config &cfg,
                                   RLAlgorithm algo, uint64_t seed, const std::string &weights_dir)
    {
        Env env(cfg);
        const int sv = static_cast<int>(features.size());
        std::vector<Episode> eps;
        if (o.approx == "tc")
        {
            Config_TC cfg_tc{.num_of_state_variables = sv,
                             .num_of_tilings = o.tilings,
                             .num_of_tiles = o.tiles,
                             .num_of_actions = kNumActions,
                             .alpha = o.alpha / (sv * o.tilings)};
            TileCoding q(cfg_tc);
            eps = train_loop(q, env, cfg, features, algo, o.gamma, o.episodes, seed, o.epsilon);
            q.save(weights_dir + "/seed-" + std::to_string(seed) + ".txt");
        }
        else
        {
            Config_RBF cfg_rbf{.num_of_state_variables = sv,
                               .num_of_tiles = o.centres,
                               .num_of_actions = kNumActions,
                               .standard_deviation = o.sigma,
                               .alpha = o.alpha / sv};
            RadialBasisFunction q(cfg_rbf);
            eps = train_loop(q, env, cfg, features, algo, o.gamma, o.episodes, seed, o.epsilon);
            q.save(weights_dir + "/seed-" + std::to_string(seed) + ".txt");
        }
        return eps;
    }
}

using namespace keepaway;

int main(int argc, char **argv)
{
    Options o;
    for (int i = 1; i < argc; ++i)
    {
        std::string arg = argv[i];
        auto next = [&]() -> std::string
        {
            if (i + 1 >= argc)
                throw std::invalid_argument("missing value after " + arg);
            return argv[++i];
        };
        try
        {
            if (arg == "--approx") o.approx = next();
            else if (arg == "--algo") o.algo = next();
            else if (arg == "--features") o.features = next();
            else if (arg == "--episodes") o.episodes = std::stoi(next());
            else if (arg == "--seeds") o.seeds = std::stoi(next());
            else if (arg == "--seed") o.seed = std::stoull(next());
            else if (arg == "--gamma") o.gamma = std::stod(next());
            else if (arg == "--epsilon") o.epsilon = std::stod(next());
            else if (arg == "--alpha") o.alpha = std::stod(next());
            else if (arg == "--tiles") o.tiles = std::stoi(next());
            else if (arg == "--tilings") o.tilings = std::stoi(next());
            else if (arg == "--centres") o.centres = std::stoi(next());
            else if (arg == "--sigma") o.sigma = std::stod(next());
            else if (arg == "--learners") o.learners = std::stoi(next());
            else if (arg == "--name") o.name = next();
            else if (arg == "--out-dir") o.out_dir = next();
            else if (arg == "--weights-dir") o.weights_dir = next();
            else if (arg == "--help" || arg == "-h")
            {
                print_usage(argv[0]);
                return 0;
            }
            else
            {
                std::cerr << "Unknown argument: " << arg << "\n";
                print_usage(argv[0]);
                return 1;
            }
        }
        catch (const std::exception &e)
        {
            std::cerr << "Bad value for " << arg << ": " << e.what() << "\n";
            return 1;
        }
    }

    if (o.approx != "tc" && o.approx != "rbf")
    {
        std::cerr << "--approx must be tc or rbf\n";
        print_usage(argv[0]);
        return 1;
    }
    if (o.algo != "qlearn" && o.algo != "sarsa")
    {
        std::cerr << "--algo must be qlearn or sarsa\n";
        return 1;
    }
    if (o.features != "full" && o.features != "reduced")
    {
        std::cerr << "--features must be full or reduced\n";
        return 1;
    }
    if (o.learners != 1 && o.learners != 3)
    {
        std::cerr << "--learners must be 1 or 3\n";
        return 1;
    }

    const RLAlgorithm algo = (o.algo == "sarsa") ? RLAlgorithm::Sarsa : RLAlgorithm::QLearning;
    const std::vector<Feature> &features = (o.features == "full") ? kFullFeatures : kReducedFeatures;
    if (o.name.empty())
        o.name = o.approx + "-" + o.algo + "-" + o.features;
    if (o.weights_dir.empty())
        o.weights_dir = "results/weights/" + o.name;

    Config cfg{.keepers = {Controller::External, Controller::External, Controller::External}};
    if (o.learners == 1)
        cfg.keepers = {Controller::External, Controller::HandCoded, Controller::HandCoded};

    std::cout << "Run:        " << o.name << "\n"
              << "Approx:     ";
    if (o.approx == "tc")
        std::cout << "tile coding (" << o.tiles << " tiles x " << o.tilings << " tilings)\n";
    else
        std::cout << "RBF (" << o.centres << " centres, sigma " << o.sigma << ")\n";
    std::cout
              << "Algorithm:  " << (algo == RLAlgorithm::Sarsa ? "Sarsa" : "Q-learning") << "\n"
              << "Features:   " << features.size() << " (" << o.features << "), learners: " << o.learners << "\n"
              << "Settings:   alpha " << o.alpha << ", gamma " << o.gamma << ", epsilon " << o.epsilon << ", "
              << o.episodes << " episodes x " << o.seeds << " seeds (" << o.seed << ", "
              << o.seed + seed_multiplier << ", ...)\n";

    std::filesystem::create_directories(o.out_dir);
    std::filesystem::create_directories(o.weights_dir);

    std::vector<Row> runs;
    for (int i = 0; i < o.seeds; ++i)
    {
        const uint64_t seed = o.seed + i * seed_multiplier;
        runs.push_back({"seed-" + std::to_string(seed), train_one(o, features, cfg, algo, seed, o.weights_dir)});
    }
    for (const Row &r : runs)
    {
        print_row(r.name, r.eps);
        print_block_averages(r.eps);
    }
    save_csv(runs, o.out_dir + "/" + o.name);
    std::cout << "CSV: " << o.out_dir << "/" << o.name << "_<timestamp>.csv, weights: " << o.weights_dir << "\n";
    return 0;
}
